cards.solution:
const daftarNilai = [80, 60, 75, 90, 45];
let jumlahLulus = 0;
for (const nilai of daftarNilai) {
  if (nilai >= 75) {
    jumlahLulus++;
  }
}
console.log(`Jumlah lulus: ${jumlahLulus}`);
